import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 102 · Christmas tips: free centerpieces from the backyard

sc("""Sweetheart, I just saw a Christmas centerpiece in a department store for eighty-nine dollars. A few pine branches, some pinecones, three red balls, and a candle. Eighty-nine dollars! My mother made one every single week of December, for nothing, from what she found in our backyard and the woods behind Elm Street. And hers were prettier. Tonight I'm going to show you how she did it.""",
   "expensive Christmas centerpiece store price tag", "EIGHTY-NINE DOLLARS")
sc("""So tonight I'm giving you nine Christmas centerpieces you can make from your own backyard, for almost nothing, and the three mistakes that make homemade ones look cheap. And stay with me, because number nine is the one my mother made for Christmas dinner every year, and the minister's wife asked to borrow it for the church altar.""",
   "natural Christmas centerpiece pine candles", "NINE CENTERPIECES")

ch("The backyard")
sc("""In my mother's day, honey, nobody bought decorations at a store. You went outside with a pair of scissors and a basket. Pine branches, holly, cedar, red berries off the bushes, pinecones, bare twigs, dried hydrangeas, even weeds from the ditch that had gone to seed and looked like little stars. It was all free, and the house smelled like the woods all December.""",
   "woman with basket gathering greenery in snow", "SCISSORS AND A BASKET")
sc("""Before you start, here's what to look for. Anything evergreen. Anything with berries. Pinecones of every size. Interesting bare branches with a nice shape. And seed pods, like milkweed or sweetgum balls. Just ask permission if it isn't your land, and never take more than a few branches from one plant. In a minute I'll tell you the biggest mistake people make with greenery.""",
   "pinecones berries branches on table", "WHAT TO LOOK FOR")

sc("""Danny and I loved gathering day, honey. The first Saturday in December, my mother would hand us each a basket and a pair of old scissors, and send us out to the woods behind Elm Street. Whoever found the biggest pinecone got to put the star on the tree. Danny cheated every year. He'd bring one from the Hendersons' yard, across the creek, where they had a giant pine. I never told on him.""",
   "two children with baskets in winter woods", "GATHERING DAY")
sc("""And bring your pinecones and branches inside the right way, sweetheart. Shake them hard outside first. Then bake the pinecones on a cookie sheet at two hundred degrees for thirty minutes, to get rid of any little bugs or spiders hiding inside. As they warm up, they open up wider, too, and look even prettier. Your kitchen will smell like a forest.""",
   "pinecones on baking sheet in oven", "BAKE YOUR PINECONES")
ch("The three mistakes")
sc("""Mistake number one. Making it too tall. A centerpiece on a dinner table has to be low enough that people can see each other across it. If you have to peek around it to pass the potatoes, it's too tall. The rule is no higher than your elbow when you're sitting down, about twelve inches. Save the tall arrangements for the mantel or the sideboard.""",
   "tall centerpiece blocking faces at table", "NO TALLER THAN YOUR ELBOW")
sc("""Mistake number two. Dry greenery. Branches cut and left out in a warm house dry out in three days, drop needles all over your tablecloth, and turn brown. Before you use them, soak the cut branches in a bucket of cool water overnight. Then mist them every couple of days. And mistake number three is too many different things. Pick three materials. Green, a color, and a texture. That's all.""",
   "branches soaking in bucket of water", "SOAK THEM OVERNIGHT")

ch("1. The pinecone bowl")
sc("""Number one, and the easiest. The pinecone bowl. Take your prettiest wooden bowl or a big glass bowl, and fill it with pinecones of different sizes. Tuck a few sprigs of cedar or holly between them. Add a handful of red berries or a few red apples. Done in two minutes. If you want a little sparkle, brush the tips of the pinecones with white glue and dip them in salt, so they look frosted.""",
   "wooden bowl of pinecones with red berries", "THE PINECONE BOWL")

ch("2. The log")
sc("""Number two. The Yule log. Find a short, fat log, about eighteen inches long, from the woodpile. Ask your husband to cut a flat side on the bottom so it doesn't roll, and drill three holes in the top for candles. Tuck greenery and pinecones around the base. It looks like something from a Christmas card, honey, and it costs nothing at all. Ours lasted twenty years.""",
   "birch log centerpiece with three candles", "THE YULE LOG")

ch("3. Mason jars")
sc("""If this is helping you, tap the like button for me, sweetheart. It helps Grandma more than you know. Number three. Mason jars down the middle of the table. Fill three or five jars with water, and put a few sprigs of greenery and berries in each one, like little bouquets. Or put a little battery candle in each jar, nestled in a handful of cranberries or Epsom salt that looks like snow.""",
   "mason jars with greenery and candles on table", "MASON JARS")

sc("""And a word about candles, honey. Real candles near dry greenery are a real fire danger. Never leave them burning when you leave the room, and keep the flame well above the branches. Or do what I do now, and use the little battery candles with a timer. They flicker like the real thing, they're safe in a pile of dry pine, and you never have to remember to blow them out.""",
   "battery candles among pine branches", "BE SAFE WITH CANDLES")
ch("4. The runner")
sc("""Number four. The greenery runner. Instead of one centerpiece, lay a long line of cedar or pine branches right down the center of the table, overlapping, like a garland. Tuck in pinecones, oranges, and little candles along the way. It looks so rich, honey, like a magazine table. And it's low, so everybody can talk. That's what I use for Christmas dinner now.""",
   "greenery runner down long dinner table", "THE RUNNER")

ch("5. Oranges and cloves")
sc("""Number five. A big bowl of oranges and clove oranges. Stud a few oranges with cloves, in swirls or stripes, leave the rest plain, and pile them in a bowl with sprigs of bay leaves or rosemary. It's beautiful, and the whole dining room smells like Christmas. And at the end of the week, you eat the plain ones. My mother called it the centerpiece you can have for dessert.""",
   "bowl of oranges with cloves and bay leaves", "CENTERPIECE FOR DESSERT")

ch("6. Bare branches")
sc("""So far, the pinecone bowl, the log, mason jars, the runner, and oranges. Number six. Bare branches in a tall vase, for a side table, not the dinner table. Find a branch with a pretty shape, birch or dogwood or even a red twig from a bush. Stand it in a big jar of rocks. Hang a few small ornaments or paper snowflakes on it. It's a little Christmas tree for nothing.""",
   "bare branches with small ornaments in vase", "A FREE LITTLE TREE")

sc("""And here's a trick for any of these, sweetheart. Use what you already own in a new way. A teapot with a sprig of holly. An old pair of ice skates hung on a hook, filled with greenery. A wooden sled leaned against the porch with a wreath. An old tin pail of pinecones on the hearth. The best decorations aren't the ones you buy. They're the ones with a story.""",
   "old ice skates filled with greenery", "THINGS WITH A STORY")
ch("7. The cake stand")
sc("""Number seven. The cake stand trick. Put a pillar candle in the center of a cake stand or a pretty plate. Circle it with greenery, then pinecones, then a ring of red berries or cranberries. Raising it up on the cake stand makes even simple things look important. I use my grandmother's milk glass cake stand. People think it came from a fancy shop.""",
   "candle on cake stand with greenery ring", "RAISE IT UP")

ch("8. The wreath")
sc("""Number eight. A wreath laid flat on the table, with candles in the middle. Take a small wreath, homemade or the cheapest one at the store, lay it flat, and set three candles of different heights in the center, on a plate. The wreath frames the candles like a picture. And when Christmas is over, it goes right back on the door. One wreath, two jobs.""",
   "wreath laid flat on table with candles inside", "ONE WREATH, TWO JOBS")

ch("9. Mother's dinner centerpiece")
sc("""And number nine, the one I promised you. My mother's Christmas dinner centerpiece. She took her big, flat wooden bread board, and on it, she built a little winter scene. Moss from the woods for the ground. Small pine branches stuck upright like little trees. Pinecones. Little rocks. A tiny wooden church that my father carved. And a little mirror for a frozen pond.""",
   "miniature winter scene on wooden board", "A LITTLE WINTER SCENE")
sc("""She sprinkled it with a little flour for snow, and set a few small candles around the edge. When the lights went down at Christmas dinner and the candles were lit, it looked like a tiny village in the snow, honey. The minister's wife saw it one year and asked to borrow it for the church altar on Christmas Eve. My mother said yes. She was proud as a peacock all week.""",
   "candlelit miniature village scene church", "PROUD AS A PEACOCK")

sc("""And after Christmas, honey, don't just throw all that greenery in the trash. Lay the branches over your flower beds outside, to protect the roots from the hard January frost. Put the pinecones in a basket by the fireplace for kindling. And save the pretty dried berries and seed pods in a shoebox for next year. My mother's shoebox of Christmas pods lasted twenty years.""",
   "pine branches laid over winter garden bed", "NOTHING WASTED")
ch("Grandma's table")
sc("""So one more time. Keep it low, no taller than your elbow. Soak your greenery overnight and mist it. Pick three materials, not ten. Then a pinecone bowl, a Yule log, mason jars, a greenery runner, oranges and cloves, bare branches, a cake stand, a flat wreath, or a little winter scene. All from your backyard, sweetheart, for almost nothing.""",
   "beautiful natural Christmas dinner table", "ALMOST NOTHING")
sc("""Tell me in the comments, honey. What's growing in your backyard that you could use? I'd love to see what you come up with. The whole playlist of Grandma's Christmas tips is right there on your screen, and I'll see you in the next video. Good night, sweetheart.""",
   "snowy backyard with evergreens", "WHAT'S IN YOUR YARD?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma102", "9 Christmas Centerpieces From Your Backyard That Look EXPENSIVE ($0)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era."],
     "christmas with tips", minutes=(10, 14.5), voice="en_US-lessac-high")
